package firewall

import (
	"strings"
	"testing"
)

// lines는 줄 목록을 개행으로 잇고 마지막에 개행을 붙인다.
func lines(ls ...string) string {
	return strings.Join(ls, "\n") + "\n"
}

// header는 모든 규칙 파일에 같은 앞부분이다.
var header = []string{
	"# Diparnux nftables rules. Generated by diparnuxd; do not edit by hand.",
	"# Manages only table inet diparnux. Other tables are not touched.",
	"table inet diparnux",
	"delete table inet diparnux",
	"table inet diparnux {",
	"\tchain input {",
	"\t\ttype filter hook input priority filter; policy drop;",
	"\t\tiif lo accept",
	"\t\tct state established,related accept",
	"\t\tct state invalid drop",
	"\t\t# ICMP (IPv4) and ICMPv6 (IPv6), needed for neighbor discovery and path MTU.",
	"\t\tmeta l4proto { icmp, icmpv6 } accept",
	"\t\t# DHCPv4 and DHCPv6 replies to this client.",
	"\t\tudp dport 68 accept",
	"\t\tudp dport 546 accept",
}

// footer는 모든 규칙 파일에 같은 뒷부분이다.
var footer = []string{
	"\t}",
	"\tchain forward {",
	"\t\ttype filter hook forward priority filter; policy drop;",
	"\t}",
	"\tchain output {",
	"\t\ttype filter hook output priority filter; policy accept;",
	"\t}",
	"}",
}

// build는 헤더, 가운데 줄들, 푸터를 이어 붙인 기대값을 만든다.
func build(middle ...string) string {
	all := append([]string{}, header...)
	all = append(all, middle...)
	all = append(all, footer...)
	return lines(all...)
}

func TestRulesetGolden(t *testing.T) {
	tests := []struct {
		name string
		o    Options
		want string
	}{
		{
			name: "everything closed",
			o:    Options{APIPort: 8080},
			want: build(),
		},
		{
			name: "API open on 8080",
			o:    Options{APIPort: 8080, APIOpen: true},
			want: build(
				"\t\t# llama-server API (LAN exposure enabled; API key required).",
				"\t\ttcp dport 8080 accept",
			),
		},
		{
			name: "API open and SSH open with default port 22",
			o:    Options{APIPort: 8080, APIOpen: true, SSHOpen: true},
			want: build(
				"\t\t# llama-server API (LAN exposure enabled; API key required).",
				"\t\ttcp dport 8080 accept",
				"\t\t# SSH.",
				"\t\ttcp dport 22 accept",
			),
		},
		{
			name: "SSH only on a custom port",
			o:    Options{APIPort: 8080, SSHOpen: true, SSHPort: 2222},
			want: build(
				"\t\t# SSH.",
				"\t\ttcp dport 2222 accept",
			),
		},
		{
			name: "SSH port is ignored while closed",
			o:    Options{APIPort: 1, SSHPort: 0},
			want: build(),
		},
		{
			name: "boundary ports 1 and 65535",
			o:    Options{APIPort: 65535, APIOpen: true, SSHOpen: true, SSHPort: 1},
			want: build(
				"\t\t# llama-server API (LAN exposure enabled; API key required).",
				"\t\ttcp dport 65535 accept",
				"\t\t# SSH.",
				"\t\ttcp dport 1 accept",
			),
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got, err := Ruleset(tc.o)
			if err != nil {
				t.Fatalf("Ruleset: %v", err)
			}
			if got != tc.want {
				t.Fatalf("ruleset mismatch\n got:\n%s\nwant:\n%s", got, tc.want)
			}
		})
	}
}

func TestRulesetRejectsBadPorts(t *testing.T) {
	tests := []struct {
		name string
		o    Options
	}{
		{"API port zero", Options{APIPort: 0}},
		{"API port negative", Options{APIPort: -1, APIOpen: true}},
		{"API port too large", Options{APIPort: 65536, APIOpen: true}},
		{"SSH port negative", Options{APIPort: 8080, SSHOpen: true, SSHPort: -1}},
		{"SSH port too large", Options{APIPort: 8080, SSHOpen: true, SSHPort: 70000}},
		{"SSH port invalid while closed", Options{APIPort: 8080, SSHPort: 99999}},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got, err := Ruleset(tc.o)
			if err == nil {
				t.Fatalf("Ruleset accepted bad ports, output:\n%s", got)
			}
			if got != "" {
				t.Fatalf("Ruleset returned text together with an error")
			}
		})
	}
}
